#!/usr/bin/env python3import reimport statistics as statsimport sysfrom pathlib import PathTEST_RE = re.compile(r"Test result for ([^:]+): accuracy=([0-9.]+), f1=([0-9.]+)")VAL_RE = re.compile(r"Validation result: loss=([0-9.]+), acc=([0-9.]+), f1=([0-9.]+)")NAME_RE = re.compile(r"gpu\d+_(.+)_seed(\d+)_(.+)\.log$")WEIGHT_RE = re.compile(r"_w([0-9p]+)_")def parse_kv_line(line, prefix):    out = {}    for part in line[len(prefix):].strip().split("|"):        if "=" not in part:            continue        key, value = part.split("=", 1)        out[key] = value    return outdef safe_float(value):    if value is None or value == "":        return None    try:        return float(value)    except ValueError:        return Nonedef safe_int(value):    if value is None or value == "":        return None    try:        return int(float(value))    except ValueError:        return Nonedef fmt(value):    if value is None:        return ""    if isinstance(value, float):        return f"{value:.6f}"    return str(value)def write_tsv(path, rows, fields):    with path.open("w", encoding="utf-8", newline="\n") as handle:        handle.write("\t".join(fields) + "\n")        for row in rows:            handle.write("\t".join(fmt(row.get(field)) for field in fields) + "\n")def mean(values):    values = [value for value in values if value is not None]    return None if not values else sum(values) / len(values)def stdev(values):    values = [value for value in values if value is not None]    if len(values) < 2:        return None    return stats.stdev(values)def rank_values(values):    indexed = [(idx, value) for idx, value in enumerate(values) if value is not None]    ranks = [None] * len(values)    if len(indexed) < 2:        return ranks    indexed.sort(key=lambda item: item[1])    pos = 0    while pos < len(indexed):        end = pos + 1        while end < len(indexed) and indexed[end][1] == indexed[pos][1]:            end += 1        avg_rank = (pos + 1 + end) / 2.0        for idx, _value in indexed[pos:end]:            ranks[idx] = avg_rank        pos = end    return ranksdef pearson(xs, ys):    pairs = [(x, y) for x, y in zip(xs, ys) if x is not None and y is not None]    if len(pairs) < 2:        return None    mx = sum(x for x, _ in pairs) / len(pairs)    my = sum(y for _, y in pairs) / len(pairs)    vx = sum((x - mx) ** 2 for x, _ in pairs)    vy = sum((y - my) ** 2 for _, y in pairs)    if vx <= 0.0 or vy <= 0.0:        return None    cov = sum((x - mx) * (y - my) for x, y in pairs)    return cov / (vx * vy) ** 0.5def spearman(xs, ys):    return pearson(rank_values(xs), rank_values(ys))def delta(left, right):    if left is None or right is None:        return None    return left - rightdef compact_weight_from_config(config):    if config == "plain":        return 0.0    match = WEIGHT_RE.search(config)    if not match:        return None    return float(match.group(1).replace("p", "."))def parse_log(path):    text = path.read_text(encoding="utf-8", errors="ignore")    name_match = NAME_RE.match(path.name)    task = name_match.group(1) if name_match else path.stem    seed = int(name_match.group(2)) if name_match else -1    config = name_match.group(3) if name_match else "unknown"    compact_weight = compact_weight_from_config(config)    tests = TEST_RE.findall(text)    source_self_f1 = source_on_target_f1 = da_f1 = None    if len(tests) >= 3:        source_self_f1 = safe_float(tests[-3][2])        source_on_target_f1 = safe_float(tests[-2][2])        da_f1 = safe_float(tests[-1][2])    rows_by_epoch = {}    pending_epoch = None    for line in text.splitlines():        if line.startswith("TIMEMATCH_PSEUDO_SUMMARY|"):            values = parse_kv_line(line, "TIMEMATCH_PSEUDO_SUMMARY|")            if values.get("stage") != "train_epoch":                continue            epoch = safe_int(values.get("epoch"))            if epoch is None:                continue            row = rows_by_epoch.setdefault(epoch, {})            row.update(                {                    "pseudo_shift": safe_int(values.get("shift")),                    "pseudo_all_f1": safe_float(values.get("all_f1")),                    "pseudo_masked_f1": safe_float(values.get("masked_f1")),                    "pseudo_coverage": safe_float(values.get("coverage")),                    "pseudo_mean_conf": safe_float(values.get("mean_conf")),                    "pseudo_pred_entropy": safe_float(values.get("pred_entropy")),                }            )        elif line.startswith("TIMEMATCH_EPOCH_SUMMARY|"):            values = parse_kv_line(line, "TIMEMATCH_EPOCH_SUMMARY|")            epoch = safe_int(values.get("epoch"))            if epoch is None:                continue            pending_epoch = epoch            row = rows_by_epoch.setdefault(epoch, {})            row.update(                {                    "epoch_loss": safe_float(values.get("loss")),                    "epoch_pseudo_all_f1": safe_float(values.get("pseudo_all_f1")),                    "epoch_pseudo_masked_f1": safe_float(values.get("pseudo_masked_f1")),                    "epoch_pseudo_coverage": safe_float(values.get("pseudo_coverage")),                    "target_updates": safe_int(values.get("target_updates")),                }            )        elif pending_epoch is not None:            match = VAL_RE.search(line)            if match:                row = rows_by_epoch.setdefault(pending_epoch, {})                row["val_loss"] = safe_float(match.group(1))                row["val_acc"] = safe_float(match.group(2))                row["val_f1"] = safe_float(match.group(3))                pending_epoch = None    rows = []    for epoch, values in sorted(rows_by_epoch.items()):        row = {            "task": task,            "seed": seed,            "config": config,            "compact_weight": compact_weight,            "epoch": epoch,            "source_self_f1": source_self_f1,            "source_on_target_f1": source_on_target_f1,            "da_f1": da_f1,            "log": path.name,        }        row.update(values)        rows.append(row)    return rowsdef build_mean_curves(rows):    grouped = {}    for row in rows:        key = (row["task"], row["compact_weight"], row["epoch"])        grouped.setdefault(key, []).append(row)    metrics = [        "pseudo_all_f1",        "pseudo_masked_f1",        "pseudo_coverage",        "pseudo_mean_conf",        "pseudo_pred_entropy",        "val_f1",        "da_f1",        "source_on_target_f1",    ]    out = []    for key, group in sorted(grouped.items()):        task, weight, epoch = key        row = {"task": task, "compact_weight": weight, "epoch": epoch, "n": len(group)}        for metric in metrics:            values = [item.get(metric) for item in group]            row[f"{metric}_mean"] = mean(values)            row[f"{metric}_std"] = stdev(values)        out.append(row)    return outdef build_delta_rows(rows):    by_key = {        (row["task"], row["seed"], row["epoch"], row["compact_weight"]): row        for row in rows        if row.get("compact_weight") is not None    }    metrics = [        "pseudo_all_f1",        "pseudo_masked_f1",        "pseudo_coverage",        "pseudo_mean_conf",        "pseudo_pred_entropy",        "val_f1",        "da_f1",        "source_on_target_f1",    ]    out = []    for task, seed, epoch, weight in sorted(by_key):        if weight == 0.0:            continue        base = by_key.get((task, seed, epoch, 0.0))        shaped = by_key.get((task, seed, epoch, weight))        if base is None or shaped is None:            continue        row = {"task": task, "seed": seed, "compact_weight": weight, "epoch": epoch}        for metric in metrics:            row[f"plain_{metric}"] = base.get(metric)            row[f"config_{metric}"] = shaped.get(metric)            row[f"delta_{metric}"] = delta(shaped.get(metric), base.get(metric))        out.append(row)    return outdef build_epoch_correlations(rows):    grouped = {}    for row in rows:        grouped.setdefault((row["task"], row["epoch"]), []).append(row)    metrics = [        "pseudo_all_f1",        "pseudo_masked_f1",        "pseudo_coverage",        "pseudo_mean_conf",        "val_f1",    ]    out = []    for (task, epoch), group in sorted(grouped.items()):        weights = [item.get("compact_weight") for item in group]        row = {"task": task, "epoch": epoch, "n": len(group)}        for metric in metrics:            values = [item.get(metric) for item in group]            row[f"spearman_weight_{metric}"] = spearman(weights, values)            row[f"pearson_weight_{metric}"] = pearson(weights, values)        out.append(row)    return outdef build_divergence_summary(delta_rows, threshold):    grouped = {}    for row in delta_rows:        grouped.setdefault((row["task"], row["compact_weight"]), []).append(row)    metrics = ["delta_pseudo_all_f1", "delta_val_f1", "delta_pseudo_coverage"]    out = []    for (task, weight), group in sorted(grouped.items()):        by_epoch = {}        for row in group:            by_epoch.setdefault(row["epoch"], []).append(row)        epoch_means = []        for epoch, epoch_rows in sorted(by_epoch.items()):            item = {"epoch": epoch}            for metric in metrics:                item[metric] = mean([row.get(metric) for row in epoch_rows])            epoch_means.append(item)        summary = {"task": task, "compact_weight": weight}        for metric in metrics:            first = None            for item in epoch_means:                value = item.get(metric)                if value is not None and value >= threshold:                    first = item["epoch"]                    break            summary[f"first_{metric}_ge_{threshold}"] = first            summary[f"last_{metric}"] = epoch_means[-1].get(metric) if epoch_means else None            summary[f"best_{metric}"] = max(                (item.get(metric) for item in epoch_means if item.get(metric) is not None),                default=None,            )        out.append(summary)    return outdef main():    if len(sys.argv) not in {2, 3}:        raise SystemExit("Usage: analyze_v243b_dose_epoch_trajectory.py LOG_DIR [THRESHOLD]")    root = Path(sys.argv[1])    threshold = float(sys.argv[2]) if len(sys.argv) == 3 else 0.02    rows = []    for path in sorted(root.glob("*.log")):        rows.extend(parse_log(path))    detail_fields = [        "task",        "seed",        "config",        "compact_weight",        "epoch",        "source_self_f1",        "source_on_target_f1",        "da_f1",        "pseudo_shift",        "pseudo_all_f1",        "pseudo_masked_f1",        "pseudo_coverage",        "pseudo_mean_conf",        "pseudo_pred_entropy",        "val_f1",        "val_acc",        "val_loss",        "epoch_loss",        "target_updates",        "log",    ]    write_tsv(root / "dose_epoch_rows.tsv", rows, detail_fields)    curves = build_mean_curves(rows)    curve_fields = list(curves[0].keys()) if curves else []    write_tsv(root / "dose_epoch_curve_mean.tsv", curves, curve_fields)    delta_rows = build_delta_rows(rows)    delta_fields = list(delta_rows[0].keys()) if delta_rows else []    write_tsv(root / "dose_epoch_delta_vs_plain.tsv", delta_rows, delta_fields)    corrs = build_epoch_correlations(rows)    corr_fields = list(corrs[0].keys()) if corrs else []    write_tsv(root / "dose_epoch_weight_correlations.tsv", corrs, corr_fields)    divergence = build_divergence_summary(delta_rows, threshold)    divergence_fields = list(divergence[0].keys()) if divergence else []    write_tsv(root / "dose_epoch_divergence_summary.tsv", divergence, divergence_fields)    print("Wrote:", root / "dose_epoch_rows.tsv")    print("Wrote:", root / "dose_epoch_curve_mean.tsv")    print("Wrote:", root / "dose_epoch_delta_vs_plain.tsv")    print("Wrote:", root / "dose_epoch_weight_correlations.tsv")    print("Wrote:", root / "dose_epoch_divergence_summary.tsv")if __name__ == "__main__":    main()